NIGHT_LOADED({"seed":1109,"generated_at":"2026-10-21T06:00:00Z","chain":[1,4,2,3,5],"frame":{"collector":"J.J.V.","intro":["Je bent de nieuwe assistent.","Op tafel ligt een briefje van de verzamelaar.","De sleutel van de voordeur zit in zijn jas, en hij is naar huis.","De klok zegt kwart over negen.","Je begint te ordenen."],"note_table":"Twaalf enveloppen invoegen.\nKast vijf blijft dicht.\nSluit af vóór twaalven.\n— J.J.V.","note_final":"Goed opgeborgen. Morgen om negen. — J.J.V.","card_desk":{"kind":"Sage","description":"In het Centraal Sagenarchief staat een leestafel met een groen kleed, en daarop een lamp met een groene kap. Langs de muur staan vijf kasten met laden vol kaarten. 's Avonds, als de anderen weg zijn, zit daar de assistent die 's avonds doorwerkte, en leest. Men ziet alleen de handen in het lamplicht.","place":"Amsterdam","prov":"N.-H.","year":1936,"code":null,"initials":"J.J.V.","teller":"de vorige assistent","note":"Niet lezen. Opbergen."},"trail_notes":["Niet door mij opgetekend. Mijn vorige assistent.","Zelfde hand. Hij werkte 's avonds door.","Zijn laatste. Daarna geen kaarten meer van hem.","Deze heeft hij niet opgeborgen. Ik ook niet."],"card_five":{"kind":"Sage","description":"Er was eens een nieuwe assistent op het Sagenarchief die 's avonds bleef om het opbergen af te maken. De verzamelaar was naar huis gegaan. De assistent zette vier kasten op orde en maakte toen ook de vijfde open, al was gezegd dat die dicht moest blijven. Daarna is de assistent niet meer gezien. De kaarten lagen keurig op volgorde, en wat de assistent daar zag, dat was ____.","place":"Amsterdam","prov":"N.-H.","year":"tomorrow","teller":"J.J.V.","initials":"J.J.V.","code":null},"final_words":["niets","mij","mijzelf","de assistent","de vorige assistent"],"door_locked":"Op slot. De sleutel zit in de jas van J.J.V.","midnight":"De klok slaat twaalf.","good_end":"Goed gedaan. Kast vijf blijft dicht.","nee":"Nee.","not_yet":"Nog niet.","into_envelope":"In de envelop.","archive_note":"Achter het schot hoef je vannacht niet.","finish_first":"Nog niet. Eerst kast {roman}.","digit_note":"{n}. Het cijfer van kast {roman}.","digit_first":"Onthouden: het slot van kast V wil er vier.","found_notes":{"chair":"Eén ligt waar ik hem gisteren neerlegde.","lamp":"Eén ligt onder de lamp. Niet de lamp verzetten.","coat":"Eén zit in mijn jas. Jas laten hangen.","typewriter":"Eén zit nog in de machine."},"floor_note":"Die hoort niet in die la.","machine_continued":"— vervolg in la 3 —","reactions":{"reopen_filed":"Die was klaar.","stalled":"Opschieten.","read_desk":"Ik had gezegd: niet lezen.","typo3":"Het staat er. Lees.","other_hand":"hij komt niet terug","five_shut":"Dicht."},"citation":"Bron: Nederlandse Volksverhalenbank, Meertens Instituut (KNAW), www.verhalenbank.nl"},"cabinets":[{"id":1,"label":"Voortekenen","digit":5,"drawers":[{"id":"1-1","type":"P2","difficulty":3.0068,"rank":0.0948,"note":"Zonder plaats. Ergens tussen de andere drie. Prik hem op de kaart.","cards":[{"id":"c1","story_id":"WEV000604","role":"target","render":{"description":"Dringend advies om een brandverzekering af te sluiten, want iemand heeft het huis in brand zien staan. Een tijd later brandt het huis af.","place":null,"prov":"Gr.","year":1962,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/42967","original":"[4.]\nMijn opa kwam ook eens bij buurman Scheper. \"Hest dien hoes in de brandkaaste Beernd?\"\n\"Nee,\" zei Beernd.\n'n Paor dagen later opa er weer heen.\n\"Beernd, hest 't hoes in de brandkaaste?\"\n\"Nee, nog nich.\"\n\"Dou hum d'r doadeluk in, want ik heb 't branden zain.\"\nEen paar maanden later, daor ging 't huis.","lang":"Standaardnederlands; Gronings","front":"original"},"home":"1-1"},{"id":"c2","story_id":"WEV005903","role":"helper","render":{"description":"Bij afbranden van zijn boerderij vertelt man dat hij lang van tevoren heeft gezien dat het huis in brand staat, maar er over heeft gezwegen.","place":"Wessingtange","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/43264","original":"Veurloop.\nJoarn leden is hier brand west. Ik huilp de boer mit alles. De man stön aal man stil te kiekn en zee:“Nôn brand e ja.”\nIk vruig:“Hou komst door bie, wat betaikent dat?”\n“t Is wol al tien joar leden”, zee e dou, “op n oavend kwam k bie hoes en dou stôn alles in lichtelaaie. k Heb dr nooit over proot, mit ganaine, man nôn brand e ja.”","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9175,7.14444]},{"id":"c3","story_id":"WEV007406","role":"helper","render":{"description":"Lichten worden gezien als voorloop van brand.","place":"Musselkanaal","prov":"Gr.","year":1963,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44126","original":"Lichten zaggen ze vrouger voak. \"dr brandt weer wat\", zeden ze, zel wel weer gauw n huus aan goan. Dat geleuf was algemain.","lang":"Gronings","front":"original"},"home":"1-1","geo":[52.9325,7.01528]},{"id":"c4","story_id":"WEV013008","role":"helper","render":{"description":"Voorspelling dat alle witte huizen afbranden komt uit, alleen witte kerk staat er nog.","place":"Bourtange","prov":"Gr.","year":1966,"code":"SINSAG 0491","initials":"F.W.","url":"https://www.verhalenbank.nl/items/show/44092","original":"Oal vrouw K. zag vrouger ale widde huuzn in Boertange brannen.\n“Zai brant aal op”, zee ze. En t oal hef nog gliek kreegn ook. Allaind de widde kerke stait dr nog.","lang":"Gronings","front":"original"},"home":"1-1","geo":[53.01,7.19028]}],"hints":["Drie plaatsen staan er al. De vierde ligt daartussen.","Binnen 2 uur lopen van Wessingtange.","Zoek Jipsingboertange op de kaart."],"lock":{"kind":"place","target_geo":[52.965,7.10139],"radius_km":6.0},"on_success":{"fill_field":{"card":"c1","field":"place","value":"Jipsingboertange"},"stack":["c1","c2","c3","c4"]},"found_card":null},{"id":"1-2","type":"P3","difficulty":1.2386,"rank":0.4673,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ051006","role":"member","render":{"description":"Een vader waarschuwt zijn kinderen 's nachts nooit middenop de weg te lopen. Ze kunnen immers op een lijkstoet stuiten.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25083","original":"Heit woe noait lije, dat wy froeger by jountiid of by nacht midden op 'e wei roannen. Sels gong er ek altyd yn 'e berm lâns. Men koe ris tsjin in lykwein oprinne, wie syn sizzen altyd.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c2","story_id":"KOOIJMAN2266","role":"intruder","render":{"description":"Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","place":"Heesselt","prov":"Gld.","year":1963,"code":"SINSAG 0333","initials":"H.K.","url":"https://www.verhalenbank.nl/items/show/127631","original":"Dat weet ik ook nog. Je werd gewaarschuwd om 's nachts niet in 't wagenspoor of in 't paardenpad te lopen. Want daar kon je de boze geesten tegenkomen.","lang":"Standaardnederlands","front":"original"},"home":"cab:4"},{"id":"c3","story_id":"CJ112406","role":"member","render":{"description":"Vanwege lijkstaties die de ruimte nodig hebben is het goed om 's nachts niet midden op de weg te lopen.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/30112","original":"Noait mat men by nacht midden op 'e wei rinne, fanwegen in lykstaesje, dy't altyd paed ha mat en dy't dan wolris tsjin jin oanstompe kin.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"},{"id":"c4","story_id":"CJ034606","role":"member","render":{"description":"Je moet nooit middenop de weg lopen, omdat je opzijgedreven kan worden door een lijkstoet.","place":"Kollumersweach","prov":"Fr.","year":1968,"code":"SINSAG 0481","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/22678","original":"Der woarde ús al hiel jong leard, noait midden op 'e wei to rinnen. Hwant it koe gebeure dat der in lykstaesje oankom en dan woarde men oan kant set.","lang":"Fries (Woudfries)","front":"original"},"home":"1-2"}],"hints":["Kijk naar de nummers in rood potlood.","Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De kaart over Heesselt hoort bij de Spoken."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":4},"on_success":{"trail_note":0,"unlock_cabinet":4,"stack":["c1","c3","c4"]}},{"id":"1-3","type":"R1","difficulty":1.0981,"rank":0.0837,"note":"De klok staat stil. Deze drie weten hoe laat het is.","cards":[{"id":"c1","story_id":"CJ022401","role":"omen","render":{"description":"Een vrouw had vijf weken voor een brand het huis al zien afbranden.","place":"Harkema","prov":"Fr.","year":1967,"code":"SINSAG 0487","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/20948","original":"Myn wiif Sjouk hat it hûs fan Ate en Ynsk hjir yn 'e Harkema sa'n fiif wike foar dat it echt opbrânde al yn 'e brân sjoen. \"Och Heare,\" sei se, \"Ate en Ynke har hûs brânt op!\"","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c2","story_id":"CJ057502","role":"omen","render":{"description":"Een man kwam bij zijn zieke moeder, en zag een doodskist in haar huis. Maar zijn moeder was niet dood en ze bleef nog vijf jaar in leven. Later is de doodskist er echt gekomen.","place":"Houtigehage","prov":"Fr.","year":1968,"code":"SINSAG 0483","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25868","original":"Heit syn mem wie o sa min. Mem wie nei har ta gong. Heit kom even letter. Hy wie oan 'e doar ta, doe stie dêr de kiste al, mei 't kleed der oerhinne. It kleed waeide in bytsje op, doe't de doar iepenkom.\nDoe't er yn 'e keamer stapte, wìe beppe der noch. Sy hat noch wol fiif jier leefd. Mar hwat heit foarút sjoen hie kom dêrom letter wol krektsa út.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"},{"id":"c3","story_id":"CJ058207","role":"omen","render":{"description":"Een man zag ergens lichten, maar in werkelijkheid was er niets. Vijf jaar later is er een tram gekomen.","place":"Opende","prov":"Gr.","year":1969,"code":"SINSAG 0492","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25990","original":"De tram is hjir kom yn 1911. Mar fiif jier earder seach myn swager de ljochten al. By Likele Pama - tichte by de Wilhelmina-hoeve - wie in wissel. Dêr seach hy de tram doe al rikjen. Hindrik de Jong hiet myn swager.","lang":"Fries (Woudfries)","front":"description"},"home":"1-3"}],"hints":["Lees ze nog eens. Ze tellen alle drie iets.","Drie keer hetzelfde getal. Zo laat is het.","5 uur. Zet de klok."],"lock":{"kind":"clock_hour","hour":5},"on_success":{"chime":5,"digit":{"value":5,"card":"c1"},"stack":["c1","c2","c3"]}}]},{"id":2,"label":"Witte wieven","digit":2,"drawers":[{"id":"2-1","type":"P4","difficulty":1.705,"rank":0.7356,"note":"Doorgescheurd. De rest ligt in de doos op tafel.","cards":[{"id":"c1","story_id":"VODA_044_03","role":"top","render":{"description":"Bart, een jongen uit Beek, gaat 's avonds laat vanuit Zeddam naar huis. Zijn kameraden vragen of hij soms bang is voor de boelekerel, omdat hij zo’n haast heeft, maar Bart zegt dat het vanwege de Witte Juffer van de Berg is.","place":"Didam","prov":"Gld.","year":1973,"code":"SINSAG 0310","initials":"H.E./J.B.","url":"https://www.verhalenbank.nl/items/show/209576","half":"top"},"home":"2-1"},{"id":"c2","story_id":"LYST030","role":"distractor","render":{"description":"Als tegenprestatie moet ze naakt door de kerk rennen. Ze doet dit met tegenzin. Later is er op de grond die ze heeft gekregen, een wit wief te zien. Men is ervan overtuigt dat de geest van de vrouw daar nog rondspookt.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c3","story_id":"ZEEUW056","role":"distractor","render":{"description":"De man ziet dat de hond de duivel is, laat zich weer naar boven brengen, waarna hij wordt vervloekt. Hij komt ziek thuis, en blijft lang ziek. Zijn hele leven blijft hij arm.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c4","story_id":"KEMP314","role":"distractor","render":{"description":"Het was lelijk met hem afgelopen als het een andere dag was geweest. De juffrouw geeft hem de mogelijkheid om haar geldkisten op te graven: die hij kan verdelen tussen hemzelf, de armen en de kerk. De volgende dinsdag gaat Drikus met zijn zwager Hannes de schat opgraven. Maar als Hannes zegt: 'kijk, daar zit de heks', zinken de kisten dieper dan ooit.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c5","story_id":"VODA_044_03","role":"bottom","render":{"description":"Hij wil haar uitnodigen om met hem te dansen op het Pinksterbier. Als hij bij de Berg komt, ziet hij een witte schim: de juffer. Ze wenkt hem om stil te houden. Ze pakt Bart vast en sleept hem mee in een wervelende rondedans. Bart blijft uiteindelijk zo slap als een vaatdoekje achter. Zijn paard is naar huis gelopen en huisgenoten komen hem zoeken en brengen hem naar huis. Bart komt er echter niet meer bovenop en overlijdt binnen drie dagen.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c6","story_id":"ZEEUW054","role":"distractor","render":{"description":"Daar waren 3 koffers met op een 'n hond, op de 2e 'n leeuw met de sleutel van de 3e in zijn bek, die de man moet pakken. Hij durft 't niet en de vrouw neemt afscheid voor 100 jaar.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c7","story_id":"KEUNING001109","role":"distractor","render":{"description":"met gevlochten manen staat, merkt dat om middernacht paard lawaai maakt en ziet bij het maken van licht een vrouw op het paard.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c8","story_id":"TINNEV065","role":"distractor","render":{"description":"Het groepje begint te rennen. Als ze uitgerend zijn vertelt de eerste man dat hij een 'grijze juffer' had gezien.","half":"bottom","code":"SINSAG 0310F"},"home":"2-1"},{"id":"c9","story_id":"ZEEUW049","role":"distractor","render":{"description":"Sindsdien heeft men juffrouw Jenne niet meer gezien..","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c10","story_id":"YPFOE088","role":"distractor","render":{"description":"Hij is dat op een gegeven ogenblik beu en wil zijn broer eens goed wakker maken. Daarbij raakt hij hem aan de slaap waarop deze sterft. De familie verhuist omdat ze het niet langer kunnen bolwerken. De lindeboom is blijven bloeien. De vermoorde jongen spookt nog steeds in de buurt rond.","half":"bottom","code":"SINSAG 0311"},"home":"2-1"},{"id":"c11","story_id":"CBOEK305","role":"distractor","render":{"description":"Als iemand haar rust verstoort, draait ze hem de nek om. Een sterke man gaat 's nachts naar het kasteel waar ze rondspookt en verdelgt haar voorgoed.","half":"bottom","code":"SINSAG 0301"},"home":"2-1"},{"id":"c12","story_id":"LAAN005","role":"distractor","render":{"description":"Er was een widde juvver, wiens kleed te lang was, waardoor iedereen erover viel. Een ziever heeft die afgeknipt en sindsdien ging het hem en zijn familie altijd goed.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"},{"id":"c13","story_id":"LYST282","role":"distractor","render":{"description":"Het meisje vraagt hem echter de volgende avond naar de schaapskooi te komen. De knecht stemt in. Als hij bij de schaapskooi staat, vliegt er opeens een witte gedaante voorbij. Vlak daarna verschijnt de boerenmeid, die bij hoog en laag beweert dat zij de witte gedaante niet geweest is. De knecht gelooft haar niet.","half":"bottom","code":"SINSAG 0310"},"home":"2-1"}],"hints":["Lees het bovenste stuk tot het laatste woord. Wat wordt er al genoemd?","Het onderste stuk noemt ‘huis’ opnieuw.","Het nummer is SINSAG 0310. Er zijn er drie met dat nummer in de doos."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c5"},"on_success":{"fuse":["c1","c5"],"stack":["c1","c5"]},"found_card":{"card":"c5"}},{"id":"2-2","type":"P3","difficulty":1.2302,"rank":0.7455,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ029903","role":"intruder","render":{"description":"Een bruidspaar is op weg naar het gemeentehuis, als de aanstaande bruidegom zijn bruid ineens een stuk uit het schort bijt. De man is een weerwolf; het meisje maakt het terstond uit.","place":"Kûkherne","prov":"Fr.","year":1953,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21918","original":"It gebeurde us dat twa jonge lju yn 'e wein sieten nei 't gemeentehûs ta. Hja soenen dy deis trouwe. Underweis yn 'e wein byt de man har in stik út 'e skelk. Hy wie in wjerwolf. Hja makke it fuort út.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:3"},{"id":"c2","story_id":"CBOEK477","role":"member","render":{"description":"Een knecht moet in een weddenschap aantonen, dat hij de spit in de Witte Wieven-kuil durft te gooien. Hij gooit en daagt het witte wief uit, dat hem achtervolgt. Met paard en al springt de knecht over de onderdeur. Het witte wief gooit de spit, dat in de middelaar van de deur blijft zitten.","place":"Bathmen","prov":"Ov.","year":1892,"code":null,"initials":"J.V.","url":"https://www.verhalenbank.nl/items/show/39631","original":"In de buurtschap Loo, op het erve Noever ging men een weddenschap aan met een knecht, dat hij het spit niet durfde gooien in de Witte-wieven-kuul; deze bevond zich daar ergens in de buurt. Hij sprong te paard en joeg derwaarts, aldaar smeet hij het spit in de kuil met de woorden:\n\nWit wieven wit\nHier breng ik oe een spit\n(of: Wat heb ie'j op oe spit?)\n\nDaarop had het wit wief gezegd:\n\nA'j zoo lang wacht\nDak mien eene schoe toeknuppe\nEn de aander toerukke\nDan zal ie'j 't gebraad wezen.\n\nDe knecht rende toen in vliegenden vaart huiswaarts, achtervolgd door het wit wief en voor de achterdeur gekomen, was de bovendeur los en de onderdeur dicht, maar het paard was nogal vlug en sprong over de onderdeur. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c3","story_id":"LYST279","role":"member","render":{"description":"Een boerenknecht brengt het spit naar de Witte Wieve. Een van hen achtervolgt hem. De knecht kan net een huis binnenvluchten. De bijl die het Witte Wief gooide komt terecht in de stiepel. Het Witte Wief kon niet sneller lopen, omdat ze problemen had met een van haar schoenen.","place":"Tilligte","prov":"Ov.","year":1937,"code":null,"initials":"B.R.","url":"https://www.verhalenbank.nl/items/show/13623","original":"Door ouden wordt nog van de Wit Wieve verteld, die alleen kwaadaardig waren, wanneer ze getergd werden. Zo wordt verteld dat een boerenknecht eens het spit bracht naar de plaats, waar zij woonden. Hij werd door eene der witte wieve achtervolgd, doch hem niet kon inhalen, omdat ze in de haast maar een schoen had kunnen aantrekken. Toen de knecht het huis binnenvluchtte, wierp ze hem met een bijl achterna, die in de steil (deurpost) terecht kwam.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"2-2"},{"id":"c4","story_id":"ENGELB_15_003","role":"member","render":{"description":"Over bestaan van witte wieven en spit in deurpost.","place":"Geesteren","prov":"Ov.","year":1979,"code":null,"initials":"H.E.","url":"https://www.verhalenbank.nl/items/show/128566","original":"H.E.: Van de witn wiew he’j doar wa mangs van heurd?\nVr.Vr.: Van de witn wiew is ok niks van woar.\nH.E.: Nee, mer te geet ok um t verhaal, he. Joa he’j hier nog zonnen beuld, zonnen witn wievnbeuld. Ne, nee, nee (door elkaar heen gepraat, ze zijn het met elkaar niet eens)\nVr. [Wolberink, Jan]: Wat hadn ze bie ouns ok zegd, oh jee no valt mie t kenneke in zee Dat stun nog moal vuur joarn in de Twentse kraant. Als ik t met ene schoen had vastgebondn, gevondn als de ander gebondn.\nA.Ve.: ... t spit nog in n stiel van n nienduur nog zitn.\nF.Ve.: t Spit brengn.","lang":"Twents","front":"original","uncatalogued":true},"home":"2-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een weerwolf.","De kaart over Kûkherne hoort bij de Weerwolven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":3},"on_success":{"trail_note":2,"unlock_cabinet":3,"stack":["c2","c3","c4"]}},{"id":"2-3","type":"R2","difficulty":1.0661,"rank":0.6949,"note":"Er staat iets op het raam. Niet afvegen.","cards":[{"id":"c1","story_id":"LYST277","role":"card","render":{"description":"Een boerenknecht komt langs de Witte Wieve en daagt ze uit. Een van hen achtervolgt hem tot huis. Hij kan net naar binnen vluchten. Ze gooit echter een knuppel naar de deur, waardoor er een stuk van de stiepel breekt.","place":"Almelo","prov":"Ov.","year":1937,"code":"SINSAG 0161","initials":"A.G.K.","url":"https://www.verhalenbank.nl/items/show/13621","original":"In Almelo gaat onder oudere personen (70 - 80 jaar) het verhaal rond van de Witte Wieve van de Alberger hei. Zij vertellen het volgende:\nAlbergen is een gehucht op zes kilometer afstand van Almelo aan de weg naar Ootmarsum. De Alberger hei strekte zich vroeger uit tussen dit gehucht en de bezittingen van Huize Almelo. Men dacht dat ze woonden in een grote tumulus, die zich in 't midden bevond. Men zegt dan, dat als voorzorgsmaatregel, dat de witte wieve niet in huis zouden komen, de boerenbehuizingen een kruis in de middenpost van de baanderdeur, \"stiepel\" genaamd, hadden aangebracht op ongeveer een meter. …","lang":"Standaardnederlands; Twents","front":"description"},"home":"2-3"},{"id":"c2","story_id":"TINNEV317","role":"sill","render":{"description":"Fietser ziet 's avonds zijn weg geblokkeerd door twee dames in het wit met paarden en moet terug (later werd hij ziek).","place":"Zevenaar","prov":"Gld.","year":1964,"code":"SINSAG 0310","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22664","stain":"twee"},"home":"2-3"},{"id":"c3","story_id":"HOL002604","role":"card","render":{"description":"Witte juffer die de weg vraagt, gooit hoed vol geld, en verdwijnt.","place":"Tiel","prov":"Gld.","year":1964,"code":"SINSAG 0310","initials":"A.R.H.","url":"https://www.verhalenbank.nl/items/show/210163","original":"Berend, den dakuil (een Van Uden) smeerde de daken van binnen aan met kalk, vandaar dat hij deze bijnaam kreeg. Eens liep Berend op de Grotebrugse grintweg bij de Twaalf Apostelen (straatje) toen een witte juffer hem de weg vroeg naar het veer. Berend zei haar die en nadat hij dit gedaan had, gooide zij hem de hoed vol met \"Berliner daolder\". Driemaal was Berend dit overkomen. Bij het veer gekomen wilde Berend haar bedanken, maar hij kreeg geen kans daartoe: zij was verdwenen.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c4","story_id":"CJ111721","role":"card","render":{"description":"Op een spookplaats spookt een vrouw in het wit. De spookvrouw is alleen 's nachts te zien. De paarden zijn erg bang voor de spookvrouw.","place":"Kollumersweach","prov":"Fr.","year":1974,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/29932","original":"Yn 'e Westerein spûke in frommes, dat sweefde yn wite klean by de wâllen lâns. Hja hie in bân om 'e rôkken hinne. Men seach har allinne by nacht.\nAs de kooplju yn 'e nacht út 'e Westerein wei mei de hynders nei de merk ta gongen, dan koenen se de hynders net fierder krije as dy wite juffer der wer spûke. Dy hynders wienen dan bang.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"},{"id":"c5","story_id":"BOEKV095","role":"card","render":{"description":"Een meisje, dat rogge sneed, werd door Ellert gekidnapt en moet dagelijks zijn vader Brannert scheren; ze snijdt hem de nek af, etc. De nageworpen bijl komt in de deurdrempel, wat nog te zien is.","place":"Amen","prov":"Dr.","year":1881,"code":"SINSAG 0161","initials":"G.J.B.","url":"https://www.verhalenbank.nl/items/show/34976","original":"In eene andere Drentsche lezing heeten de roovers Ellert en Brannert en wordt gezegd dat hun hol te vinden was tusschen Zweeloo en Schoonoord. Het meisje had groene rogge gesneden op den esch (1) toen Ellert haar gevangen nam. Hij dwingt haar zijn vader dagelijks te scheren en zij maakt nu tijdens zijne afwezigheid gebruik van het scheermes om dezen te dooden. Overigens is het verhaal hetzelfde. De bijl vliegt in den drempel van de huisdeur, waar dit nog zichtbaar is. \n\n1. bouwland.","lang":"Standaardnederlands","front":"description"},"home":"2-3"},{"id":"c6","story_id":"CJ007910","role":"card","render":{"description":"Bij Hattum de Vries in het laantje spookte 's nachts altijd een wit wijf. De mensen durfden er 's nachts niet te komen, want ze werden er door dat witte wijf aan de kant gedreven naar het meertje toe. Zonder dat ze zelf iets deden, kwamen ze in het meertje terecht.","place":"Oudega","prov":"Fr.","year":1966,"code":"SINSAG 0310","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/17053","original":"By Hattum de Vries yn it loantsje spoeke nachts altyd in wyt wiif. De minsken doarsten dêr nachts noait to kommen. Hwant sy waerden dêr stadich troch dat wite wiif oan kant treaun nei de dobbe ta. Sûnder dat se it sels fornamen kommen se yn 'e dobbe torjochte.","lang":"Fries (Woudfries)","front":"description"},"home":"2-3"}],"hints":["Lees het van achteren naar voren.","Het begint met een Z.","Zevenaar. Leg die kaart op de vensterbank."],"lock":{"kind":"card_to_object","card":"c2","object":"window","text":"Zevenaar"},"on_success":{"digit":{"value":2,"card":"c2","word":"twee","stained":"c2"},"stack":["c1","c2","c3","c4","c5","c6"]}}]},{"id":3,"label":"Weerwolven","digit":7,"drawers":[{"id":"3-1","type":"P5","difficulty":0.679,"rank":0.375,"note":"De vertellers spreken elkaar tegen. Houd de oudste aan.","cards":[{"id":"c1","story_id":"LYST274","role":"variant","render":{"description":"Knecht, die 's nachts in een wolf verandert, verdwijnt als de boer onder zijn bed een wolfshuid vindt en verbrandt.","place":"Drogteropslagen","prov":"Dr.","year":1937,"code":"SINSAG 0824","initials":"K.J.","url":"https://www.verhalenbank.nl/items/show/13538","original":"Vroeger was hier een knecht, die 's nachts in een wolf veranderde en het de mensen dan lastig maakte. Onder zijn bed vond de boer op zekere dag een wolfshuid en verbrandde die. Sedert was de knecht verdwenen.\n(Verteld door een zeventig-jarige).","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c2","story_id":"VVUNL301","role":"variant","render":{"description":"Een knecht wordt weerwolf door een leren riem, die hij verstopt. Deze wordt gevonden en in de oven verbrand; meteen komt de verdachte knecht te paard aansnellen, maar wordt tegengehoudcen en zegt als de riem verbrand is: \"Ik ben verlost!\"","place":"Echt","prov":"L.","year":1920,"code":"SINSAG 0824","initials":"F.S.S.","url":"https://www.verhalenbank.nl/items/show/35840","original":"De weerwolf \n\nOp de hoeve Bosscherhof woonde eertijds een knecht die een lederen riem bezat, welke de macht had, hem, indien hij hem omgordde, te betoveren als weerwolf. Geheimzinnig en zorgvuldig werd deze band telkenmale door de knecht verstopt en wat men ook deed, hoe men ook spiedde, men vond hem nooit. En geregeld hadden de mensen uit de omtrek, die laat huiswaarts keerden, de weerwolf te dragen. En ook iedereen herkende steeds de knecht. Men gaf elkander raad om wanneer men overvallen werd, de weerwolf op een of andere manier te prikken of te krab-ben tot hij bloed voelde of zag. Dan was men gered. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c3","story_id":"LINSSEN002605","role":"variant","render":{"description":"Knecht die om middernacht door velg in zwarte kat verandert, is verlost na verbranden van velg.","place":"Baexem","prov":"L.","year":1962,"code":"SINSAG 0824","initials":"G.H.L.","url":"https://www.verhalenbank.nl/items/show/208342","original":"Volgens tweede verteller was er op Nelishof te Tungelroy een knecht die elke nacht tussen twaalf en een uur afwezig was. Door een raampje ging hij naar buiten. Hij klom dan op de schansenhoop en kwam er als kat af. De boer had hem bespied en gemerkt dat boven op de schansenhoop een velg lag van een karwiel. Die had de boer daar niet neergelegd en hij zocht verband tussen de spokerij (zwarte kat) en dat karwiel.\nDit zou hij vernietigen als de knecht afwezig was. Op zekere dag had hij hem met schapen naar Antwerpen gestuurd. Toen hij een dag weg was stak de boer zijn bakoven aan en wierp de velg erin.\nOp hetzelfde moment verscheen de knecht en wilde de oven in. Het gelukte slechts met drie man om hem daarvan te weerhouden. …","lang":"Standaardnederlands","front":"description"},"home":"3-1"},{"id":"c4","story_id":null,"role":"summary","render":{"description":"In Limburg werd een dier gezien: ____. (volgens de oudste opname)","place":null,"year":null,"code":null,"initials":"J.J.V.","summary":true},"home":"3-1"}],"hints":["Kijk naar de jaartallen.","De oudste is uit 1920.","Op die kaart staat een dier. Welk?"],"lock":{"kind":"word","salt":"057c831a0ec70409","accepted_hashes":["2d259ae6306a77688d20ae15173553d4ce6b41c854374e97f0fa0ccd09a80f03","6ee3dbaf99f8bf726084cee00dc9c17181967dfdc1d286b59b1e5a562662b3d8","96a824bb665c40eebe3805f90552236c457aeb520653eb47ed98d6db678464d2","adc6f8136157be418b610eb0dabda30b314212cfc51a796ac2cd5227d8d7edff","be3c6d57e894d0bb7d415f17aa5dba49823930941169663f79f572dab27ad5aa","c870753275ef14e07073850d5a52732984c4beac9e1491cd9b4d0962434c1466"],"fill":"c4"},"on_success":{"fill_field":{"card":"c4","field":"blank","value":"typed"},"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"3-2","type":"P3","difficulty":1.4262,"rank":1.1567,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"GENDT029","role":"member","render":{"description":"Een man staat 's nachts onder een boom. Om middernacht valt er een wolvenvel op hem en wordt hij een weerwolf tot het weer licht wordt.","place":"Gendt","prov":"Gld.","year":1965,"code":null,"initials":"M.H.D.","url":"https://www.verhalenbank.nl/items/show/49659","original":"In Hulhuze gebeurdenet, dat zon kjel soaves onder ’n boom gieng stoan. Snachs as de klok twoalf sloeg, viel dan ’t vel op ’m en hé’j veraanderde ien ’n werwolf. En dan kontie d’r op uut goan. Smèrs vörda ’t lich wier, giengtie wer onder den boom stoan. En dan nomen ze ’m het vel wer af. En kos ie nor huus goan.","lang":"Gendts (Achterhoeks)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c2","story_id":"LIJST024","role":"intruder","render":{"description":"Op een avond ziet een man een donker wezen waarvan hij meent dat het de duivel is.","place":"Lopik","prov":"Utr.","year":1954,"code":null,"initials":"J.P.B.","url":"https://www.verhalenbank.nl/items/show/14743","original":"I. De duivel\n1. Zijn U verhalen bekend over mensen, die de duivel gezien hebben of omgang met hem hebben gehad (met hem gedanst hebben, met hem kaart hebben gespeeld), of kent U andere verhalen, waarin de duivel een rol speelt?\nGelieve elk verhaal te noteren op een afzonderlijk blad papier en in elk verhaal duidelijk aan te duiden hoe de duivel voorgesteld wordt (met bokshorens, bokspoten, paardenhoeven, sik, staat enz.).\n\nBijlage\n't Was den boze geweest\nZelf kreeg ik niet zo lang geleden 't volgende te horen:\n\"Meester, wilt U de jongens eens waarschouwe, want als ze uit school langs komme, dan gooien ze met steene en kluite tegen de deur.\"\n\"Zeker de Oudste, ik zal ze onderhanden nemen.\"\n\"Ja meester, 't is wat. …","lang":"Utrechts","front":"original","uncatalogued":true},"home":"cab:5"},{"id":"c3","story_id":"GENDT089","role":"member","render":{"description":"Een groepje kaarters heeft het idee dat één van hen een weerwolf is. Als deze man weg wil gaan 's avonds houden ze hem vast en laten ze hem niet gaan. Als zijn wolvenvel door de schoorsteen komt valt het in het vuur en verbrandt. Nu is de man bevrijd.","place":"Gendt","prov":"Gld.","year":1965,"code":null,"initials":"M.H.D.","url":"https://www.verhalenbank.nl/items/show/49725","original":"Mien voader het wel es verteld, dat ze vroeger duk same gienge koarte, erges bé’j iemes ien de buurt. D’r waster één ien de ploeg, wor ze van dochte, dattie duk gieng werwolve. Op ’n keer ware ze weer on ’t koarte. Op zekere tied wou die kjel weg. Mar d’aander wouwe ’m nie loate goan. Ze hemmen ’m vasgegrope en ’m nie losgeloate, al gieng ie nog zo d’rop. Opens kwam er ’n wolvevel dör de schorsten valle. Da verbraandde. En toe zeitie: “Nou ziet ’k teraf! As ik los gekomme was en ik had ’t vel kunne kriege, dan ha’k hier alles kort en klein geslage”.","lang":"Gendts (Achterhoeks)","front":"original","uncatalogued":true},"home":"3-2"},{"id":"c4","story_id":"LYST027","role":"member","render":{"description":"Een jongeman is een weerwolf. Zijn vrienden willen een grap met hem uithalen. Op een verjaardag laten ze hem niet vertrekken. Opeens valt er een wolfsvel uit de schoorsteen in het vuur. Het verbrandt en de jongeman is verlost.","place":"Ochten","prov":"Gld.","year":1953,"code":null,"initials":"J.G.K.","url":"https://www.verhalenbank.nl/items/show/13241","original":"Wjerwolve\nA. v.d. Halert oud 56 jaar vertèlde me het volgende verhaôl, dà' tie wir geheurt hà' van z'n vaôder:\nIn Heuze' (hier wo' bedoeld Opheusden) was een jonge vent, die òk wjerwolve' moes' (die drang van mòtte' was bij iedere wjerwolf bekènd). Z'n kammeraôi hadde' afgesproke' um der is een keer tusse' te neme'. Die tijd braak al gaauw aôn, één van z'n kammeraôi was jaôrig , en ze wiere' allemaôl uitgenodig' um de verjaôrdag mee te viere', ok degene die wjerwolve' kon. Jongès zee'e ze tigge' mekaôr, es ie nou kom', dan laôte' we 'm niet gaon. Zo zate' ze dan 's aôves bij mekaôr, daôr wier meinig borreltje gedronke', en onderhaand vloog de tijd um. En de zogenaamde wjerwolf zat mar op de klok te kijke', eindelijk zee tie: Jongès ik gaô. …","lang":"Gelders","front":"original","uncatalogued":true},"home":"3-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over de duivel.","De kaart over Lopik hoort bij de duivel."],"lock":{"kind":"card_to_cabinet","card":"c2","cabinet":5},"on_success":{"trail_note":3,"unlock_cabinet":5,"stack":["c1","c3","c4"]}},{"id":"3-3","type":"R3","difficulty":1.079,"rank":0.6923,"note":"Als er geklopt wordt: tel. Die kaart onder de deur.","cards":[{"id":"c1","story_id":"CJ071310","role":"card","render":{"description":"Een van acht zoons was een weerwolf. Een weerwolf kon zich nooit vol eten, hij had altijd nog honger.","place":"Houtigehage","prov":"Fr.","year":1969,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/28045","original":"As der acht jonges wienen, dy't op elkoar folgen yn in húshâlding, dan wie ien fan dy acht in wjerwolf. Dat wie ien dy't noait sêd koe, dy't neat fan ûnpas kom.","lang":"Fries (Woudfries)","front":"description"},"home":"3-3"},{"id":"c2","story_id":"TINNEV043","role":"card","render":{"description":"Twee mannen zijn grasstengels aan het snijden, als de ene man aan de andere vraagt of hij hem eens wil zien. Meteen daarop ligt er een wolf in het gras. De man wil nooit meer met de ander werken.","place":"Didam","prov":"Gld.","year":1944,"code":"SINSAG 0804","initials":"A.T.","url":"https://www.verhalenbank.nl/items/show/22389","original":"30.\nOp een andere kier vroeg Dorus aan Peter, toe ze aan 't smele sui'je ware: \"Wi'j um is zien?\" Medeen derop lei een grote wolf ien 't gres. Peter wol van toe af aan de niet meer met Dorus op uut.","lang":"Liemers","front":"description"},"home":"3-3"},{"id":"c3","story_id":"LYST008","role":"card","render":{"description":"Een boerenknecht haalt iedere nacht precies om twaalf uur een hoepeltje uit de lindeboom. Hij hangt de hoepel om zijn nek en verandert in een weerwolf. Hij loopt een tijdje rond en verscheurt alles wat er in zijn buurt komt. Hierna wordt hij weer gewoon mens. De boer vindt zijn gedrag maar vreemd en vraagt raad aan de pastoor. De pastoor heeft door dat de boerenknecht een weerwolf is, en adviseert de boer om de knecht een boodschap te laten doen waarbij hij nooit om middernacht weer thuis kan zijn. Op de afgesproken nacht haalt de pastoor om middernacht de hoepel uit de boom. De knecht staat onder die boom en ziet alles. Hij vlucht en komt nooit meer terug.","place":"Erp","prov":"N.-Br.","year":1953,"code":"SINSAG 0803","initials":"F.W.J.S.","url":"https://www.verhalenbank.nl/items/show/13222","original":"De Weerwolf\nEen boerenknecht kroop 's nachts klokslag 12 uur in de lindenboom voor de boerderij. Boven in de boom hing voor gewone mensen onzichtbaar een hoepeltje. Dat hing de knecht om zijn hals. Als ie uit de boom geklauterd was, liep ie in de gedaante van een hond weg en verscheurde alles wat hem in de weg kwam. Als ie een tijd zo rondgelopen had, was ie weer gewoon mens. Na een tijd was het de boer, bij wie de weerwolf in dienst was, opgevallen, dat zijn knecht nacht op nacht weg was. Hij ging naar de pastoor en die had het zaakje meteen door. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"},{"id":"c4","story_id":"CJ039818","role":"door","render":{"description":"Een van zeven op elkaar volgende zonen is een weerwolf.","place":"Harkema","prov":"Fr.","year":1968,"code":"TM 3107","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/23535"},"home":"3-3"},{"id":"c5","story_id":"LYST189","role":"card","render":{"description":"Drie mensen vertellen dat zij 's avonds laat een grote hond met vurige ogen zijn tegengekomen, die bij hen op de rug sprong. Pas bij de grens van het stuk land sprong hij eraf en verdween. De hond verdween bij een boerderij die al als \"niet pluis\" bekend stond, omdat de knecht van die boerderij vertelde dat de koeien enkele malen om klokslag middernacht opsprongen terwijl de staldeuren vanzelf opensprongen.","place":"Puiflijk","prov":"Gld.","year":1957,"code":"SINSAG 0801","initials":"C.v.d.P.","url":"https://www.verhalenbank.nl/items/show/13453","original":"Spookdieren\nMij is eens door drie verschillende personen op zeer verschillende tijden meegedeeld dat op de Waaldijk tussen Boven-Leeuwen en Druten 's avonds in pikdonker plotseling een abnormale grote hond, die plotseling verscheen, hen zwijgend met vurige ogen volgde en even plots aan de grens van Druten verdween. Beide personen waren niet bijgelovig maar hadden van angst 't zweet op de rug staan van angst, temeer daar de hond verdween bij een boerderij waar 't niet \"pluis\" scheen te zijn. Een knecht op deze boerderij vertelde mij eens hoe verscheidene malen 's nachts de koeien om klokslag 12 uur opsprongen en staldeuren openvlogen zonder 'n aanwijsbare oorzaak. …","lang":"Standaardnederlands","front":"description"},"home":"3-3"}],"hints":["Wacht op het kloppen. Tel het.","Een oneven getal.","7 keer. Die kaart."],"lock":{"kind":"card_to_object","card":"c4","object":"door","n":7},"on_success":{"digit":{"value":7,"card":"c1"},"stack":["c1","c2","c3","c5"]}}]},{"id":4,"label":"Spoken","digit":3,"drawers":[{"id":"4-1","type":"P6","difficulty":3.2415,"rank":0.5659,"note":"Elk verhaal één getal. In deze volgorde.","cards":[{"id":"c1","story_id":"CJ029902","role":"clip1","render":{"description":"Twee meisjes worden op weg naar huis opgeschrikt door een plaagbeest.","place":"Kûkherne","prov":"Fr.","year":1953,"code":"SINSAG 0256","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/21917","original":"Twa famkes soenen op in joun nei hûs ta.\nUnderweis op 'e Foksegatten kom der in beest njonken har. It wie in pleachbeest.","lang":"Fries (Woudfries)","front":"description"},"home":"4-1"},{"id":"c2","story_id":"VODA_035_10","role":"clip2","render":{"description":"Twee vissers willen 's middags een dutje doen op hun schuit. Ze zijn ver uit de kust en er is geen wind. Net voordat ze in slaap vallen, horen ze iemand uit het water komen aan de voorkant van het schip en aan de achterkant weer van het schip stappen. Als ze gaan kijken zijn er alleen wat rimpels en bellen op het water te zien.","place":"Terneuzen","prov":"Zl.","year":1971,"code":"SINSAG 0478","initials":"H.E./J.B.","url":"https://www.verhalenbank.nl/items/show/132017","original":"Vaoder het ook es […] wa beleefd. Hij was nog nie zo oud en lag mee zijn broer, die bij hem op d’n hengstenschuit voer, op ‘ne werme zomermiddag ‘nen kilometer van de wal voor Ossenisse ten anker. Ze waoren al van ’s morgensvroeg in touw geweest. D’r was geen vleugke wind en ze wilden zo, op de middag, ‘nen tukske doen op ’t dek van de schuit. Ze legden hulder neer op ‘nen ouw’ baal, maor net da ze in slaop zouen gaon, hoorden vader en zijn broer allebei dat ‘r iënen voor op de schuit uit ’t water trapten en dat ‘r hij van achter weer af stapt’n. ‘t Ging allemaol zo gauw, da ze toen ze recht kwamen op stille wateren voor en achter de schuit wa rimpels en een soort van bruising zagen. Wa ’t geweest is da he’n ze nooit geweet’n.","lang":"Standaardnederlands; Zeeuws","front":"description"},"home":"4-1"},{"id":"c3","story_id":"YPFOE107g","role":"clip3","render":{"description":"In Eastermar is een keer een huis afgebrand. De hond die in het huis zat is daarbij verbrand. Die nacht om twaalf uur hebben ze de hond horen blaffen.","place":"Goutum","prov":"Fr.","year":1978,"code":"SINSAG 0333","initials":"Y.P.","url":"https://www.verhalenbank.nl/items/show/12459","original":"Spoekjende dieren\nYn Eastermar stiet in spultsje, dat is in kear ôfbrând en doe is der in hynder yn ferbrând. It hûs is neitiid wer opboud, mar dan nachts om tolve oere hearden se dat hynder slaan. Gosling hat der wenne en dy sei: 'It is wier! It is wier! Ik hearde him dêr no en dan nachts wol omhuffen. Hy sloech yn deadsneed tsjin 'e skudden'.","lang":"Fries","front":"description"},"home":"4-1"},{"id":"c4","story_id":"CJ058009","role":"inside","render":{"description":"Een vrouw beweerde voor niets bang te zijn, omdat ze een rein geweten had. Maar op een keer werd ze lastig gevallen door een plaagbeest. Ze gooide een steen naar het dier, maar het bleef gewoon zitten. Toen is de vrouw naar een huis in de buurt gegaan, en die mensen hebben haar weer thuisgebracht.","place":"Opende","prov":"Gr.","year":1969,"code":"SINSAG 0256","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/25948","original":"Tsjinoer it hûs fan Japik Kuipers stie nòch in hûs. Dêr wenne IJe de Vries yn. Myn âldste suster wie dêr alris to helpen. Doe soe mem dêr ek hinne, hwat letter op 'e dei. Hja wie sahwat oan 'e Wilhelmina-hoeve ta.\nMem wie noait bang, hwant mem sei: \"Ik haw in rein geweten, dan kin der my neat gebeure.\"\nDoe kom der in swart ding op har ta. 't Wie hiel great en 't hie swart, krolderich hier.\nIt bleau stiif by har. Mem hie in stien krige en hie 't beest dêr mei smite sild.\nMar doe woarde se doch hwat binaud, hwant it beest bleau stean en sy koe net fierder.\nDoe hie mem nei in hûs ta gong, dat der flak by wie.\nDe heit en de soan út dat hûs ha har thús brocht.\n't Wie krekt as wie dat swarte ding yn 'e sleat wei woarn.","lang":"Fries (Woudfries)","front":"original","note":"Deze bewaar ik apart."},"home":"4-1"}],"hints":["Elk verhaal telt.","Het eerste getal is 2.","2 — 2 — 12."],"lock":{"kind":"number3","salt":"057c831a0ec70409","accepted_hashes":["189b3ee34715ac7d832ad596d38ebcb5369457d488ff7af95e6613f55cf71a08"]},"on_success":{"stack":["c1","c2","c3","c4"]},"found_card":{"card":"c3"}},{"id":"4-2","type":"P3","difficulty":1.212,"rank":0.7143,"note":"Eén hoort hier niet. Terug naar zijn eigen kast.","cards":[{"id":"c1","story_id":"CJ015603","role":"intruder","render":{"description":"Een visser ziet een juffer in witte kleren en besluit haar te volgen. Het witte wief verdwijnt echter even snel als ze verschenen is.","place":"Broeksterwâld","prov":"Fr.","year":1967,"code":null,"initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/19893","original":"Douwe syn broer Anne Feddema hie to fiskjen west. Hy hie nei 't tichtset ta west en farde de Lyts út wei werom de kant nei de brêge út. Doe kom der in juffer oan yn sniewite klean. Hy tocht: Ik wol wite hwer't dy keart, dat hy hie 't eech net fan har ôf. Doe't er oan har ta wie, died er de fêstsetter yn 'e kant en krekt doe't er dat die, wie de wite juffer fuort.","lang":"Fries (Woudfries)","front":"original","uncatalogued":true},"home":"cab:2"},{"id":"c2","story_id":"DYKFRIES2153","role":"member","render":{"description":"Op de Leppedijk spookte een gloeiend veulen rond. Een boerenmeid was tot laat in het dorp gebleven en moest alleen naar huis. Toen ze gewaarschuwd werd voor het spookveulen, beweerde ze dat ze het dier haar kousenband in de bek zou doen en op het beest naar huis zou rijden. Toen ze het dier echter daadwerkelijke ontmoette, schrok ze hevig en rende ze naar huis.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69329","original":"Op den Leppedijk, niet ver van Oldeboorn, spookte voorheen een gloeiend veulen. Eene boerenmeid was op zekeren avond wat laat in het dorp gebleven en toen haar gezegd werd, dat het veulen haar wel kon ontmoeten, zei ze, dat zij hem dan haar kouseband in den bek zou doen en op hem naar huis rijden. Maar toen zij, op den weg gekomen, het veulen eensklaps vóór zich zag met den bek wijd opengesperd, toen liep zij zoo hard zij kon om tehuis te komen.","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"},{"id":"c3","story_id":"DYKFRIES2191","role":"member","render":{"description":"Liep iemand daar bij nacht, dan kon hij onverwachts een wit veulen in vliegende vaart zich voorbij zien snellen, waarna het plotseling verdween.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69795","uncatalogued":true},"home":"4-2"},{"id":"c4","story_id":"DYKFRIES2156","role":"member","render":{"description":"Een boer uit Westdongeradeel had regelmatig ontmoetingen met een plaaggeest. Het dier liep steeds met hem mee naar huis, maar deed hem verder niets. De boer zorgde ervoor dat hij het dier altijd een stukje roggebrood kon aanbieden. Zijn dienstmeid beweerde dat zij dapperder zou zijn en dat ze als zij het dier tegenkwam, er wel op naar huis zou rijden. Toen zij het dier eens tegenkwam, zette het zijn voorpoten op haar schouders, waardoor de meid gedwongen was het gewicht van het dier mee te dragen op haar weg naar huis.","place":"Goutum","prov":"Fr.","year":1896,"code":null,"initials":"W.D.","url":"https://www.verhalenbank.nl/items/show/69345","original":"In Westdongeradeel woonde weleer een boer die veel last had van een plaagbeest. Was de man 's avonds bij duister op weg naar zijn huis, dan kwam hem meest altijd zulk een spookdier op zijde. Het vergezelde hem tot aan zijn erf. Eens zelfs was het meegegaan over het bruggetje, dat aan den weg over de gracht lag. Maar dat was dan ook alles; eigenlijk kwaad deed het hem niet. Hij zorgde altijd een stuk roggebrood bij zich te hebben, waarop hij 't beest dan onthaalde. Dit scheen daar smaak in te vinden, nam het gretig aan en liet den boer ongedeerd. Maar de man was toch altijd ontsteld als hij in huis kwam. Zijne dienstmeid vond dit wel wat dwaas en schroomde ook niet voor hare meening uit te komen. …","lang":"Standaardnederlands","front":"original","uncatalogued":true},"home":"4-2"}],"hints":["Drie kaarten vertellen in wezen hetzelfde. De vierde niet.","De vierde gaat over een witte vrouw.","De kaart over Broeksterwâld hoort bij de Witte wieven."],"lock":{"kind":"card_to_cabinet","card":"c1","cabinet":2},"on_success":{"trail_note":1,"unlock_cabinet":2,"stack":["c2","c3","c4"]}},{"id":"4-3","type":"R4","difficulty":1.1123,"rank":0.25,"note":"Als de machine begint: laten uittikken. Het vervolg zit hierin.","cards":[{"id":"c1","story_id":"CJ081906","role":"top","render":{"description":"Een turfschipper die steeds opgeschrikt wordt door een naakt kindje achter het schip raadpleegt de dominee. De dominee vraagt het kind - dat allang overleden is - waarom het geen rust kan vinden.","place":"Dokkum","prov":"Fr.","year":1970,"code":"SINSAG 0402","initials":"A.A.J.","url":"https://www.verhalenbank.nl/items/show/32618","half":"top"},"home":"4-3"},{"id":"c2","story_id":"CBAK0016","role":"half","render":{"description":"Na de dood van de vrouw wordt het huis afgebroken. Vanwege de bewering dat het er spookte omdat er onrechtvaardig geld verborgen is wordt naar een schat gezocht.","half":"bottom","code":"SINSAG 0401"},"home":"4-3"},{"id":"c3","story_id":"CJ081906","role":"bottom","render":{"description":"Het kind blijkt op die plaats verdronken en vervolgens zonder doodskleed begraven te zijn. Het kind verzoekt de dominee de middelste van drie vrouwen om een doodshemd te vragen. De wens wordt vervuld en de dominee reikt het kind het doodskleed aan met een houten lepel. Nu de wens van het kind vervuld is vindt het rust.","half":"bottom","code":"SINSAG 0402","stain":"drie"},"home":"4-3"},{"id":"c4","story_id":"CJ041201","role":"half","render":{"description":"De eerste nachten na de begrafenis werd de man wakker omdat er op de ruiten getikt werd. Hij hoorde dan zijn dode vrouw vragen om haar gouden been. De derde nacht heeft hij het been buiten voor de deur gezet. De volgende ochtend was het verdwenen, en zijn vrouw is nooit meer bij hem komen spoken.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c5","story_id":"CJ061713","role":"half","render":{"description":"Daarna verdwijnt hij.Bearn is bang geweest. Het mannetje is pikzwart en snuift de hele tijd.","half":"bottom","code":"SINSAG 0478"},"home":"4-3"},{"id":"c6","story_id":"CJ065118","role":"half","render":{"description":"Want als men er niet aan kan voldoen, dan krijgt de dode nooit rust in zijn graf en gaat hij spoken.","half":"bottom","code":"SINSAG 0402"},"home":"4-3"},{"id":"c7","story_id":"WEV015701","role":"half","render":{"description":"Boer vertelt dat vrouw die er is vermoord zo nu en dan spookt.","half":"bottom","code":"SINSAG 0450"},"home":"4-3"}],"hints":["Lees wat de machine getypt heeft, tot het laatste woord.","Het vervolg noemt ‘dominee’ opnieuw.","Het nummer is SINSAG 0402. Er zijn er maar drie in de envelop."],"lock":{"kind":"card_match","top_card":"c1","bottom_card":"c3","object":"typewriter"},"on_success":{"fuse":["c1","c3"],"type_line":"Verteller: de vorige assistent.","digit":{"value":3,"card":"c1","word":"drie","stained":"c3"},"stack":["c1","c2","c3","c4","c5","c6","c7"]}}]},{"id":5,"label":"De duivel","digit":null,"drawers":[]}]});
